/** Comment metadata with optional inline floor seeds. Numeric comment/user IDs are an existing v1 limitation. */
data class CommentItem(
    /** Existing v1 positive numeric comment ID within JavaScript safe-integer bounds. */
    val id: Long,
    /** Plain-text content. */
    val content: String,
    /** Comment author's display nickname, not a SocialUser record. */
    val user: String,
    /** Comment avatar display URL/text preserved by the compatibility record. */
    val avatar: String,
    /** Display time text. */
    val time: String,
    /** Known nonnegative like count. */
    val likedCount: Int,
    /** Explicit desired/current liked state, not a toggle. */
    val liked: Boolean,
    /** Known nonnegative reply count. */
    val replyCount: Int,
    /** Reply attribution preserved from upstream. */
    val beReplied: List<CommentReply> = emptyList(),
    /** Existing v1 numeric user ID within JavaScript safe-integer bounds. */
    val userId: Long,
    /** Comment time in Unix epoch milliseconds. */
    val timeMs: Long,
    /** Numeric top-level comment identity. */
    val parentCommentId: Long,
    /** Public location attribution text. */
    val ipLocation: String,
    /** Whether upstream marks the comment as hot. */
    val isHot: Boolean,
    /** Inline floor seeds, not proof that a complete floor page has been fetched. */
    val topReplies: List<CommentItem> = emptyList(),
) {
    fun write(w: WireWriter) { with(w) {
        long(this@CommentItem.id)
        string(this@CommentItem.content)
        string(this@CommentItem.user)
        string(this@CommentItem.avatar)
        string(this@CommentItem.time)
        int(this@CommentItem.likedCount)
        bool(this@CommentItem.liked)
        int(this@CommentItem.replyCount)
        list(this@CommentItem.beReplied) { v -> v.write(this) }
        long(this@CommentItem.userId)
        long(this@CommentItem.timeMs)
        long(this@CommentItem.parentCommentId)
        string(this@CommentItem.ipLocation)
        bool(this@CommentItem.isHot)
        list(this@CommentItem.topReplies) { v -> v.write(this) }
    } }
    fun values(): Map<String, Any?> = mapOf(
        "id" to id,
        "content" to content,
        "user" to user,
        "avatar" to avatar,
        "time" to time,
        "likedCount" to likedCount,
        "liked" to liked,
        "replyCount" to replyCount,
        "beReplied" to beReplied.map { it.values() },
        "userId" to userId,
        "timeMs" to timeMs,
        "parentCommentId" to parentCommentId,
        "ipLocation" to ipLocation,
        "isHot" to isHot,
        "topReplies" to topReplies.map { it.values() },
    )
    companion object {
        fun read(r: WireReader): CommentItem = with(r) { CommentItem(
            long(),
            string(),
            string(),
            string(),
            string(),
            int(),
            bool(),
            int(),
            list { CommentReply.read(this) },
            long(),
            long(),
            long(),
            string(),
            bool(),
            list { CommentItem.read(this) },
        ) }
        fun fromValues(v: Map<String, Any?>): CommentItem = CommentItem(
            valueLong(v["id"]),
            valueString(v["content"]),
            valueString(v["user"]),
            valueString(v["avatar"]),
            valueString(v["time"]),
            valueInt(v["likedCount"]),
            valueBool(v["liked"]),
            valueInt(v["replyCount"]),
            valueList(v["beReplied"] ?: emptyList<Any?>()).map { CommentReply.fromValues(valueObject(it)) },
            valueLong(v["userId"]),
            valueLong(v["timeMs"]),
            valueLong(v["parentCommentId"]),
            valueString(v["ipLocation"]),
            valueBool(v["isHot"]),
            valueList(v["topReplies"] ?: emptyList<Any?>()).map { CommentItem.fromValues(valueObject(it)) },
        )
    }
}

/** Comments, total and effective sort plus the next opaque cursor. */
data class CommentPage(
    /** Ordered comments bounded by the request limit. */
    val comments: List<CommentItem> = emptyList(),
    /** Known total count, at least the number of items returned. */
    val totalCount: Long,
    /** Known continuation state; null means unknown, not false. */
    val hasMore: Boolean,
    /** Next opaque token. When comments.page is used, an empty token is a real value, not null. */
    val cursor: String,
    /** 1 = recommended, 2 = hot, 3 = latest. Responses carry the effective server sort. */
    val sortType: Int,
) {
    fun write(w: WireWriter) { with(w) {
        list(this@CommentPage.comments) { v -> v.write(this) }
        long(this@CommentPage.totalCount)
        bool(this@CommentPage.hasMore)
        string(this@CommentPage.cursor)
        int(this@CommentPage.sortType)
    } }
    fun values(): Map<String, Any?> = mapOf(
        "comments" to comments.map { it.values() },
        "totalCount" to totalCount,
        "hasMore" to hasMore,
        "cursor" to cursor,
        "sortType" to sortType,
    )
    companion object {
        fun read(r: WireReader): CommentPage = with(r) { CommentPage(
            list { CommentItem.read(this) },
            long(),
            bool(),
            string(),
            int(),
        ) }
        fun fromValues(v: Map<String, Any?>): CommentPage = CommentPage(
            valueList(v["comments"] ?: emptyList<Any?>()).map { CommentItem.fromValues(valueObject(it)) },
            valueLong(v["totalCount"]),
            valueBool(v["hasMore"]),
            valueString(v["cursor"]),
            valueInt(v["sortType"]),
        )
    }
}

